mapper.insert:
INSERT INTO erp_time_table
(yy, mm, dayname, period_no, start_time, end_time, class_key, unit_key, grade_key, user_code, created_at, time_table_key, center_code)
values (#{yy}, #{mm}, #{dayname}, #{periodNo}, #{startTime}, #{endTime}, #{classKey}, #{unitKey}, #{gradeKey}, #{userCode}, SYSDATETIME(), #{timeTableKey}, #{centerCode});

mapper.update:
UPDATE erp_time_table_code
SET time_table_label = #{label}
WHERE time_table_key = #{timeTableKey}

mapper.insert:
INSERT INTO erp_time_table_assign
    (student_id, time_table_key, week)
values (#{studentId}, #{timeTableKey}, #{weekNo});

mapper.update:
UPDATE erp_student_attendance
SET attendance_date = #{attendanceDate},
    is_before_send  = '1'
WHERE student_id = #{studentId}
  AND time_table_key = #{timeTableKey}
  AND week = #{week}
  AND is_before_send IS NULL

UPDATE erp_student_attendance
SET is_after_send = '1'
where student_id = #{studentId}
  AND time_table_key = #{timeTableKey}
  AND week = #{week}
  AND is_after_send IS NULL

mapper.insert:
INSERT INTO erp_monthly_score
(question1, question2, question3, question4, question5, question6, question7, question8, student_id, yy, mm, time_table_key, created_at)
VALUES (0, 0, 0, 0, 0, 0, 0, 0, #{studentId}, #{yy}, #{mm}, #{timeTableKey}, SYSDATETIME());

mapper.select:
SELECT COUNT(*)
FROM erp_time_table_assign
WHERE time_table_key = #{timeTableKey}

SELECT ta.time_table_key,
        t.user_code,
        t.class_key
FROM erp_time_table_assign ta
         JOIN erp_time_table t ON ta.time_table_key = t.time_table_key
         JOIN erp_class_code c ON t.class_key = c.class_key
WHERE student_id = #{studentId}
  AND c.class_type = #{classType}
  AND t.yy = #{yy}
  AND t.mm = #{mm}

